  if new<=tree:break
  tree|=new
 ids=tree;states=get('/session/status');permissions=[x for x in get('/permission') if x.get('sessionID') in tree];questions=[x for x in get('/question') if x.get('sessionID') in tree]
 for x in permissions:
  if x['id'] in seen:continue
  seen.add(x['id']);m=x.get('metadata',{});minimal={'id':x['id'],'sessionID':x.get('sessionID'),'permission':x.get('permission'),'patterns':x.get('patterns'),'operation':{k:m[k] for k in ['command','filepath','directories','parentDir'] if k in m}}
  raw=json.dumps(minimal,ensure_ascii=False)
  if len(raw)>6000:minimal={'id':x['id'],'sessionID':x.get('sessionID'),'requires_more_detail':True}
  emit({'kind':'permission','request':minimal})
 blocked={x['sessionID'] for x in questions}
 if fully_stopped(states,tree,blocked):
  idle_at=idle_at or time.monotonic()
  if time.monotonic()-idle_at>=10 and not stop_notified:
   stop_notified=True;emit({'kind':'tree_stopped','sessionIds':sorted(tree),'blockingQuestions':questions,'lastError':{i:v for i,v in last_error.items() if i in tree}})
 else:idle_at=None;stop_notified=False
 return len(tree)
